// ID do aplicativo no Gupshup (Configuracoes > ID do aplicativo).
// Ja preenchido com o app Suplelive; se um dia trocar de app, atualize aqui.
const APP_ID = 'abc8678f-7774-44f4-b7d0-71f71af860d0';
if (!APP_ID) throw new Error('Preencha o APP_ID neste no (ID do aplicativo no Gupshup).');
return [{ json: { appId: APP_ID } }];

// A resposta do Gupshup vem como {status:'success', templates:[...]}.
// Aqui vira o formato que o LiveOps desenha nos cards do espelho.
const r = $json || {};
const lista = Array.isArray(r.templates) ? r.templates : [];
const ord = { APPROVED: 0, PENDING: 1, SUBMITTED: 1, REJECTED: 2, FAILED: 2 };
const templates = lista
  .filter(t => t && String(t.status || '').toUpperCase() !== 'DELETED')
  .map(t => ({
    nome: t.elementName || t.id || '—',
    categoria: t.category || '',
    idioma: t.languageCode || '',
    status: String(t.status || '').toUpperCase(),
    texto: t.data || '',
    motivo: t.reason || '',
    atualizado: t.modifiedOn ? new Date(t.modifiedOn).toLocaleDateString('pt-BR') : ''
  }))
  .sort((a, b) => ((ord[a.status] ?? 3) - (ord[b.status] ?? 3)) || a.nome.localeCompare(b.nome));
return [{ json: { templates } }];
